select id, customer_id, start_date, end_date, monthly_fee, last_value(monthly_fee) ignore nulls over (partition by status order by end_date, id rows between unbounded preceding and current row) as last_known_monthly_fee, round(monthly_fee / sum(monthly_fee) over (partition by plan), 4) as monthly_fee_share, ntile(5) over (partition by status, customer_id order by monthly_fee desc, id) as monthly_fee_bucket, avg(monthly_fee) over (partition by date_trunc('WEEK', start_date) order by monthly_fee, id rows between 3 preceding and current row) as monthly_fee_avg_3, avg(monthly_fee) over (partition by plan order by start_date, id rows between 5 preceding and current row) as monthly_fee_avg_5 from subscriptions
